import math
import pandas as pd
from collections import Counter

def entropy(labels):
    n = len(labels)
    if n == 0:
        return 0.0
    counts = Counter(labels)
    return -sum((c / n) * math.log2(c / n) for c in counts.values() if c > 0)

def information_gain(df, feature_col, target_col):
    total_ent = entropy(df[target_col].tolist())
    n = len(df)
    weighted_ent = 0.0
    for _, subset in df.groupby(feature_col):
        weighted_ent += (len(subset) / n) * entropy(subset[target_col].tolist())
    return total_ent - weighted_ent

import pandas as pd

def naive_bayes_predict(df, feature_cols, target_col, test_sample):
    n = len(df)
    scores = {}
    for cls, sub in df.groupby(target_col):
        prior = len(sub) / n
        likelihood = 1.0
        for col in feature_cols:
            likelihood *= (sub[col] == test_sample[col]).sum() / len(sub)
        scores[cls] = prior * likelihood
    best_cls = max(scores, key=scores.get)
    return best_cls, scores

