from itertools import combinations

def apriori_level2(transactions, min_support):
    n = len(transactions)
    items = sorted({item for t in transactions for item in t})
    freq1 = {}
    for it in items:
        fs = frozenset([it])
        sup = sum(1 for t in transactions if fs.issubset(t)) / n
        if sup >= min_support:
            freq1[fs] = sup
    kept_items = sorted([next(iter(fs)) for fs in freq1])
    freq2 = {}
    for a, b in combinations(kept_items, 2):
        fs2 = frozenset([a, b])
        sup2 = sum(1 for t in transactions if fs2.issubset(t)) / n
        if sup2 >= min_support:
            freq2[fs2] = sup2
    return freq1, freq2

def hac_first_merge_manhattan(points):
    n = len(points)
    def manhattan(p1, p2):
        return sum(abs(a - b) for a, b in zip(p1, p2))
    best_pair = None
    best_dist = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            d = manhattan(points[i], points[j])
            if d < best_dist:
                best_dist = d
                best_pair = (i, j)
    i, j = best_pair
    others = {}
    for k in range(n):
        if k not in (i, j):
            others[k] = min(manhattan(points[i], points[k]), manhattan(points[j], points[k]))
    return best_pair, best_dist, others

