import math
import pandas as pd
from collections import Counter

def _ent(labels):
    n = len(labels)
    return -sum((c / n) * math.log2(c / n) for c in Counter(labels).values() if c > 0)

def c45_gain_ratio(df, feature_col, target_col):
    n = len(df)
    total_ent = _ent(df[target_col].tolist())
    weighted_ent = 0.0
    split_info = 0.0
    for _, sub in df.groupby(feature_col):
        p = len(sub) / n
        weighted_ent += p * _ent(sub[target_col].tolist())
        if p > 0:
            split_info -= p * math.log2(p)
    gain = total_ent - weighted_ent
    gain_ratio = gain / split_info if split_info > 0 else 0.0
    return gain, split_info, gain_ratio

def parse_arff_basic(arff_text):
    relation = ''
    attrs = []
    rows = []
    in_data = False
    for raw in arff_text.splitlines():
        line = raw.strip()
        if not line or line.startswith('%'):
            continue
        low = line.lower()
        if not in_data:
            if low.startswith('@relation'):
                relation = line.split(None, 1)[1]
            elif low.startswith('@attribute'):
                attrs.append(line.split()[1])
            elif low.startswith('@data'):
                in_data = True
        else:
            rows.append([cell.strip() for cell in line.split(',')])
    return relation, attrs, rows

