import numpy as np

def minmax_train_test(train_vals, test_vals):
    tr = np.array(train_vals, dtype=float)
    te = np.array(test_vals, dtype=float)
    min_v = np.min(tr)
    max_v = np.max(tr)
    span = max_v - min_v
    if span == 0:
        return np.zeros_like(tr), np.zeros_like(te)
    return (tr - min_v) / span, (te - min_v) / span

