def equal_width_binning(values, num_bins):
    mn, mx = min(values), max(values)
    if mx == mn:
        return [0] * len(values)
    width = (mx - mn) / num_bins
    res = []
    for v in values:
        idx = int((v - mn) / width)
        if idx >= num_bins:
            idx = num_bins - 1
        res.append(idx)
    return res

