import math
import pandas as pd
from collections import Counter

def _ent(labels):
    n = len(labels)
    return -sum((c / n) * math.log2(c / n) for c in Counter(labels).values() if c > 0)

def _gain(df, feat, target):
    n = len(df)
    tot = _ent(df[target].tolist())
    w_ent = sum((len(sub) / n) * _ent(sub[target].tolist()) for _, sub in df.groupby(feat))
    return tot - w_ent

def build_id3_tree(df, feature_cols, target_col):
    labels = df[target_col].tolist()
    if len(set(labels)) == 1:
        return labels[0]
    if not feature_cols:
        return Counter(labels).most_common(1)[0][0]
    best_feat = max(feature_cols, key=lambda f: _gain(df, f, target_col))
    rem = [f for f in feature_cols if f != best_feat]
    branches = {}
    for val, sub in df.groupby(best_feat):
        branches[val] = build_id3_tree(sub, rem, target_col)
    return {best_feat: branches}

