def weighted_nn_kredit(train_cases, new_case, weights, diff_sim):
    w_sum = sum(weights.values())
    scores = {}
    best_name, best_lbl, best_score = None, None, -1.0
    for row in train_cases:
        num = 0.0
        for feat, wt in weights.items():
            sim = 1.0 if row[feat] == new_case[feat] else diff_sim[feat]
            num += sim * wt
        score = num / w_sum
        scores[row['nama']] = score
        if score > best_score:
            best_score = score
            best_name = row['nama']
            best_lbl = row['layak']
    return best_name, best_lbl, scores

import pandas as pd

def naive_bayes_laplace(df, feature_cols, target_col, test_sample, alpha=1.0):
    n = len(df)
    vocab_sizes = {col: df[col].nunique() for col in feature_cols}
    scores = {}
    for cls, sub in df.groupby(target_col):
        prior = len(sub) / n
        likelihood = 1.0
        for col in feature_cols:
            cnt = int((sub[col] == test_sample[col]).sum())
            likelihood *= (cnt + alpha) / (len(sub) + alpha * vocab_sizes[col])
        scores[cls] = prior * likelihood
    return max(scores, key=scores.get), scores

