import math

def naive_bayes_log_scores(priors, likelihoods_per_class):
    log_scores = {}
    for cls, prior in priors.items():
        total = math.log(prior) + sum(math.log(p) for p in likelihoods_per_class[cls])
        log_scores[cls] = total
    return max(log_scores, key=log_scores.get), log_scores

from itertools import combinations

def run_apriori_full(transactions, min_support, min_confidence):
    n = len(transactions)
    items = sorted({it for t in transactions for it in t})
    freq = {}
    curr = []
    for it in items:
        fs = frozenset([it])
        sup = sum(1 for t in transactions if fs.issubset(t)) / n
        if sup >= min_support:
            freq[fs] = sup
            curr.append(fs)
    k = 2
    while curr:
        curr_set = set(curr)
        cands = set()
        for i in range(len(curr)):
            for j in range(i + 1, len(curr)):
                u = curr[i] | curr[j]
                if len(u) == k:
                    if all(frozenset(sub) in curr_set for sub in combinations(u, k - 1)):
                        cands.add(u)
        next_curr = []
        for c in sorted(cands, key=lambda s: tuple(sorted(s))):
            sup = sum(1 for t in transactions if c.issubset(t)) / n
            if sup >= min_support:
                freq[c] = sup
                next_curr.append(c)
        curr = next_curr
        k += 1
    rules = []
    for fs, sup in freq.items():
        if len(fs) < 2:
            continue
        for r in range(1, len(fs)):
            for ant_t in combinations(fs, r):
                ant = frozenset(ant_t)
                con = fs - ant
                conf = sup / freq[ant]
                if conf >= min_confidence:
                    lift = conf / freq[con]
                    rules.append((ant, con, sup, conf, lift))
    return freq, rules

from collections import Counter

def prepare_fpgrowth_transactions(transactions, min_support_count):
    counts = Counter(item for t in transactions for item in t)
    freq = {k: v for k, v in counts.items() if v >= min_support_count}
    ordered = []
    for t in transactions:
        kept = [it for it in t if it in freq]
        kept.sort(key=lambda it: (-freq[it], it))
        ordered.append(kept)
    return freq, ordered

from itertools import combinations
from collections import defaultdict

def mine_conditional_base(suffix, cond_pattern_base, min_support_count):
    counts = defaultdict(int)
    for prefix, cnt in cond_pattern_base:
        plist = sorted(prefix)
        for r in range(1, len(plist) + 1):
            for comb in combinations(plist, r):
                pat = frozenset(comb) | frozenset([suffix])
                counts[pat] += cnt
    return {pat: c for pat, c in counts.items() if c >= min_support_count}

