def hac_merge_history(points, linkage='single'):
    def man(p1, p2):
        return sum(abs(a - b) for a, b in zip(p1, p2))
    clusters = [[i] for i in range(len(points))]
    history = []
    while len(clusters) > 1:
        best_pair = None
        best_dist = float('inf')
        for i in range(len(clusters)):
            for j in range(i + 1, len(clusters)):
                pair_dists = [man(points[a], points[b]) for a in clusters[i] for b in clusters[j]]
                if linkage == 'single':
                    d = min(pair_dists)
                elif linkage == 'complete':
                    d = max(pair_dists)
                else:
                    d = sum(pair_dists) / len(pair_dists)
                if d < best_dist:
                    best_dist = d
                    best_pair = (i, j)
        i, j = best_pair
        c1, c2 = clusters[i], clusters[j]
        history.append(((tuple(c1), tuple(c2)), best_dist))
        merged = sorted(c1 + c2)
        clusters = [c for idx, c in enumerate(clusters) if idx not in (i, j)]
        clusters.append(merged)
    return history

