def build_arff_string(relation, attributes, rows):
    lines = [f'@relation {relation}']
    for name, typ in attributes:
        if isinstance(typ, (list, tuple)):
            t_str = '{' + ', '.join(str(v) for v in typ) + '}'
        else:
            t_str = str(typ)
        lines.append(f'@attribute {name} {t_str}')
    lines.append('@data')
    for r in rows:
        lines.append(','.join('?' if v is None else str(v) for v in r))
    return '\n'.join(lines)

def validate_arff(arff_text):
    has_rel = False
    attr_cnt = 0
    in_data = False
    for raw in arff_text.splitlines():
        line = raw.strip()
        if not line or line.startswith('%'):
            continue
        low = line.lower()
        if not in_data:
            if low.startswith('@relation'):
                has_rel = True
            elif low.startswith('@attribute'):
                attr_cnt += 1
            elif low.startswith('@data'):
                in_data = True
        else:
            cols = [c.strip() for c in line.split(',')]
            if len(cols) != attr_cnt:
                return False, f'Jumlah kolom ({len(cols)}) != jumlah atribut ({attr_cnt})'
    if not has_rel or attr_cnt == 0 or not in_data:
        return False, 'Header @relation/@attribute/@data tidak lengkap'
    return True, 'OK'

