    a = sum(euc(point, p) for p in same_cluster_others) / len(same_cluster_others)
    b = min(sum(euc(point, p) for p in cl) / len(cl) for cl in other_clusters)
    s = (b - a) / max(a, b) if max(a, b) > 0 else 0.0
    return a, b, s

